-- Phase 5c: Typo repair — whakae → whakaae, meeting-copilot → hui
-- Generated by Kaihanga 2026-05-13 (uncovered during Phase 4b verification)
--
-- Two orphaned agent_id values in agent_toolsets that don't match agent_prompts:
--
--   1. 'whakae' (2 wirings) — Lovable's WHAKAE was missing an 'a'.
--      The correct te reo is 'whakaae' (whaka-ae, "to agree/consent", 7 chars).
--      Phase 4b incorrectly lowercased WHAKAE to 'whakae' (6 chars) instead of merging into 'whakaae'.
--
--   2. 'meeting-copilot' (2 wirings) — Lovable's 'meeting-copilot' agent was a sha256-identical
--      duplicate of 'hui'. Phase 1 collapsed agent_prompts to single row under 'hui'.
--      Phase 4b kept the meeting-copilot toolset rows. Remap to hui.
--
-- The 17 other orphaned agent_ids (anchor, aroha, auaha, cellar, compass, compliance-scanner,
-- harvest, haven, ledger, mahara, mana, motor, pilot, saffron, sentinel, shield, ta) are
-- left as-is — they represent intent to use Lovable agents that don't have prod prompts.
-- Defer to follow-up: Kate decides which to materialise (port the prompt) vs delete.

BEGIN;

-- ── whakae (typo) → whakaae (canonical) ──
INSERT INTO agent_toolsets (agent_id, tool_name)
SELECT 'whakaae', tool_name FROM agent_toolsets WHERE agent_id = 'whakae'
ON CONFLICT (agent_id, tool_name) DO NOTHING;

DELETE FROM agent_toolsets WHERE agent_id = 'whakae';

-- ── meeting-copilot → hui ──
INSERT INTO agent_toolsets (agent_id, tool_name)
SELECT 'hui', tool_name FROM agent_toolsets WHERE agent_id = 'meeting-copilot'
ON CONFLICT (agent_id, tool_name) DO NOTHING;

DELETE FROM agent_toolsets WHERE agent_id = 'meeting-copilot';

COMMIT;

